     1	package br.com.loja.pedidos.checkout;
     2	
     3	import java.util.List;
     4	import java.util.Map;
     5	
     6	/**
     7	 * The purchase data as received. Nothing is rejected while parsing: values of the wrong shape become null
     8	 * (or 0 for installments) so that {@link CheckoutService} reports problems in the documented order.
     9	 */
    10	public record CheckoutRequest(
    11	        String cpf,
    12	        String email,
    13	        List<Item> items,
    14	        String zipCode,
    15	        String region,
    16	        String shippingMethod,
    17	        boolean couponInformed,
    18	        String coupon,
    19	        String paymentMethod,
    20	        int installments,
    21	        String clubTier) {
    22	
    23	    public record Item(String sku, Integer quantity) {
    24	    }
    25	
    26	    public static CheckoutRequest parse(Map<String, Object> body) {
    27	        if (body == null) {
    28	            body = Map.of();
    29	        }
    30	        Map<?, ?> customer = body.get("customer") instanceof Map<?, ?> m ? m : Map.of();
    31	        List<Item> items = null;
    32	        if (body.get("items") instanceof List<?> list) {
    33	            items = list.stream().map(CheckoutRequest::item).toList();
    34	        }
    35	        return new CheckoutRequest(text(customer.get("cpf")), text(customer.get("email")), items,
    36	                text(body.get("zipCode")), text(body.get("region")), text(body.get("shippingMethod")),
    37	                body.get("coupon") != null, text(body.get("coupon")), text(body.get("paymentMethod")),
    38	                installments(body), text(body.get("clubTier")));
    39	    }
    40	
    41	    private static Item item(Object raw) {
    42	        if (!(raw instanceof Map<?, ?> m)) {
    43	            return new Item(null, null);
    44	        }
    45	        Integer quantity = null;
    46	        if (m.get("quantity") instanceof Integer i) {
    47	            quantity = i;
    48	        } else if (m.get("quantity") instanceof Long l && l >= Integer.MIN_VALUE && l <= Integer.MAX_VALUE) {
    49	            quantity = l.intValue();
    50	        }
    51	        return new Item(text(m.get("sku")), quantity);
    52	    }
    53	
    54	    private static int installments(Map<String, Object> body) {
    55	        Object raw = body.get("installments");
    56	        if (raw == null) {
    57	            return 1;
    58	        }
    59	        if (raw instanceof Integer i) {
    60	            return i;
    61	        }
    62	        if (raw instanceof Long l && l >= Integer.MIN_VALUE && l <= Integer.MAX_VALUE) {
    63	            return l.intValue();
    64	        }
    65	        return 0;
    66	    }
    67	
    68	    private static String text(Object value) {
    69	        return value instanceof String s ? s : null;
    70	    }
    71	}
