     1	package br.com.loja.pedidos.checkout;
     2	
     3	import br.com.loja.pedidos.common.Money;
     4	import java.math.BigDecimal;
     5	import java.util.Optional;
     6	
     7	/** Customer region: sets the insurance charge and the extra dispatch days of carrier deliveries. */
     8	public enum Region {
     9	    SOUTHEAST("0.01", null, 0),
    10	    SOUTH("0.01", null, 0),
    11	    MIDWEST("0.015", null, 0),
    12	    NORTH("0.025", "30.00", 3),
    13	    NORTHEAST("0.02", "30.00", 2);
    14	
    15	    private final BigDecimal insuranceRate;
    16	    private final BigDecimal insuranceCap;
    17	    private final int dispatchDelayDays;
    18	
    19	    Region(String insuranceRate, String insuranceCap, int dispatchDelayDays) {
    20	        this.insuranceRate = new BigDecimal(insuranceRate);
    21	        this.insuranceCap = insuranceCap == null ? null : new BigDecimal(insuranceCap);
    22	        this.dispatchDelayDays = dispatchDelayDays;
    23	    }
    24	
    25	    public BigDecimal insurance(BigDecimal productsSubtotal) {
    26	        BigDecimal value = Money.percent(productsSubtotal, insuranceRate);
    27	        return insuranceCap != null && value.compareTo(insuranceCap) > 0 ? insuranceCap : value;
    28	    }
    29	
    30	    public int dispatchDelayDays() {
    31	        return dispatchDelayDays;
    32	    }
    33	
    34	    public static Optional<Region> parse(String code) {
    35	        for (Region region : values()) {
    36	            if (region.name().equals(code)) {
    37	                return Optional.of(region);
    38	            }
    39	        }
    40	        return Optional.empty();
    41	    }
    42	}
