   169	    private static void requireTransition(StoredOrder stored, OrderStatus next) {
   170	        if (!stored.order().status().canTransitionTo(next)) {
   171	            throw ApiException.conflict("OPERATION_NOT_ALLOWED");
   172	        }
   173	    }
