   149	    /** Cancels an order whose row is already locked, giving back whatever the payment had taken. */
   150	    private void cancelLocked(StoredOrder stored) {
   151	        boolean wasPaid = stored.order().status() == OrderStatus.PAID;
   152	        if (wasPaid) {
   153	            stored.order().items().stream().sorted(Comparator.comparing(Order.Item::sku))
   154	                    .forEach(i -> products.incrementStock(i.sku(), i.quantity()));
   155	        }
   156	        orders.updateStatus(stored.order().id(), OrderStatus.CANCELLED);
   157	        StoredOrder cancelled = reload(stored.order().id());
   158	        listeners.forEach(l -> l.onCancelled(cancelled, wasPaid));
   159	    }
   160	
   161	    private StoredOrder lock(String id) {
   162	        return orders.findForUpdate(id).orElseThrow(OrderService::notFound);
   163	    }
   164	
   165	    private StoredOrder reload(String id) {
   166	        return orders.find(id).orElseThrow(OrderService::notFound);
   167	    }
