   179	    private static Instant parseInstant(String text) {
   180	        if (text == null) {
   181	            return null;
   182	        }
   183	        try {
   184	            return OffsetDateTime.parse(text).toInstant();
   185	        } catch (RuntimeException e) {
   186	            return null;
   187	        }
   188	    }
