     1	package br.com.loja.pedidos.payment;
     2	
     3	import br.com.loja.pedidos.common.Money;
     4	import java.math.BigDecimal;
     5	import java.math.MathContext;
     6	import java.math.RoundingMode;
     7	import org.springframework.stereotype.Component;
     8	
     9	@Component
    10	public class CreditCardPayment implements PaymentMethod {
    11	
    12	    private static final int INTEREST_FREE_UP_TO = 3;
    13	    private static final int MAX_INSTALLMENTS = 12;
    14	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
    15	
    16	    @Override
    17	    public String code() {
    18	        return "CREDIT_CARD";
    19	    }
    20	
    21	    @Override
    22	    public boolean allowsInstallments(int installments) {
    23	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
    24	    }
    25	
    26	    @Override
    27	    public PaymentCharge charge(BigDecimal orderTotal, int installments, boolean couponInformed) {
    28	        BigDecimal n = BigDecimal.valueOf(installments);
    29	        if (installments <= INTEREST_FREE_UP_TO) {
    30	            return new PaymentCharge(orderTotal, orderTotal.divide(n, 2, RoundingMode.HALF_EVEN));
    31	        }
    32	        // Price table: total × i ÷ (1 − (1 + i)^−n)
    33	        MathContext mc = MathContext.DECIMAL128;
    34	        BigDecimal discount = BigDecimal.ONE.divide(BigDecimal.ONE.add(MONTHLY_RATE).pow(installments, mc), mc);
    35	        BigDecimal installment = Money.round(orderTotal.multiply(MONTHLY_RATE)
    36	                .divide(BigDecimal.ONE.subtract(discount), mc));
    37	        return new PaymentCharge(installment.multiply(n), installment);
    38	    }
    39	}
