    10	import org.springframework.stereotype.Repository;
    11	
    12	@Repository
    13	public class ProductRepository {
    14	
    15	    private static final String COLUMNS = "sku, name, price, weight_kg, stock, discontinued";
    16	
    17	    private final JdbcClient jdbc;
    18	
    19	    public ProductRepository(JdbcClient jdbc) {
    20	        this.jdbc = jdbc;
    21	    }
    22	
    23	    public Optional<Product> find(String sku) {
    24	        return jdbc.sql("SELECT " + COLUMNS + " FROM products WHERE sku = :sku")
    25	                .param("sku", sku).query(this::map).optional();
    26	    }
    27	
    28	    public List<Product> findAll(Collection<String> skus) {
    29	        if (skus.isEmpty()) {
    30	            return List.of();
    31	        }
    32	        return jdbc.sql("SELECT " + COLUMNS + " FROM products WHERE sku IN (:skus)")
    33	                .param("skus", skus).query(this::map).list();
    34	    }
    35	
    36	    /** Locks the product row until the end of the transaction and returns its current stock. */
    37	    public int lockStock(String sku) {
    38	        return jdbc.sql("SELECT stock FROM products WHERE sku = :sku FOR UPDATE")
    39	                .param("sku", sku).query(Integer.class).single();
    40	    }
    41	
    42	    public void decrementStock(String sku, int quantity) {
    43	        int updated = jdbc.sql("UPDATE products SET stock = stock - :q WHERE sku = :sku AND stock >= :q")
    44	                .param("q", quantity).param("sku", sku).update();
    45	        if (updated != 1) {
    46	            throw new IllegalStateException("stock would become negative for " + sku);
    47	        }
    48	    }
    49	
    50	    public void incrementStock(String sku, int quantity) {
    51	        jdbc.sql("UPDATE products SET stock = stock + :q WHERE sku = :sku")
    52	                .param("q", quantity).param("sku", sku).update();
    53	    }
    54	
    55	    private Product map(ResultSet rs, int row) throws SQLException {
    56	        BigDecimal weight = rs.getBigDecimal("weight_kg").stripTrailingZeros();
    57	        if (weight.scale() < 2) {
    58	            weight = weight.setScale(2);
    59	        }
    60	        return new Product(rs.getString("sku"), rs.getString("name"), rs.getBigDecimal("price").setScale(2),
    61	                weight, rs.getInt("stock"), rs.getBoolean("discontinued"));
    62	    }
    63	}
