    22	    public void createIfAbsent(String cpf, String email) {
    23	        try {
    24	            jdbc.sql("INSERT INTO customers (cpf, email, credit_balance) "
    25	                    + "SELECT :cpf, :email, 0 WHERE NOT EXISTS (SELECT 1 FROM customers WHERE cpf = :cpf)")
    26	                    .param("cpf", cpf).param("email", email).update();
